-- M2.1: dados clínicos estruturados, somente DEV, leitura clínica autorizada.
DO $$ BEGIN IF current_database() <> 'oncopharma_dev' THEN RAISE EXCEPTION 'Somente DEV'; END IF; END $$;
CREATE TABLE clinical_allergies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), patient_id uuid NOT NULL REFERENCES patients(id), substance text NOT NULL, reaction text, status text NOT NULL CHECK(status IN ('active','inactive','unconfirmed')), recorded_at timestamptz NOT NULL, source_reference text NOT NULL, UNIQUE(organization_id,patient_id,source_reference));
CREATE TABLE clinical_measurements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), patient_id uuid NOT NULL REFERENCES patients(id), kind text NOT NULL CHECK(kind IN ('weight','height','bsa','temperature','blood_pressure','heart_rate')), value numeric(12,3) NOT NULL, unit text NOT NULL, measured_at timestamptz NOT NULL, source_reference text NOT NULL, UNIQUE(organization_id,patient_id,source_reference));
CREATE TABLE clinical_labs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), patient_id uuid NOT NULL REFERENCES patients(id), analyte_code text NOT NULL, analyte_label text NOT NULL, result_value numeric(16,4), unit text NOT NULL, reference_low numeric(16,4), reference_high numeric(16,4), collected_at timestamptz NOT NULL, source_reference text NOT NULL, UNIQUE(organization_id,patient_id,source_reference));
CREATE TABLE clinical_medication_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), patient_id uuid NOT NULL REFERENCES patients(id), medication text NOT NULL, dose_value numeric(12,3), dose_unit text, route text, frequency_text text, status text NOT NULL CHECK(status IN ('draft','active','stopped','completed','cancelled')), ordered_at timestamptz NOT NULL, source_reference text NOT NULL, UNIQUE(organization_id,patient_id,source_reference));
CREATE TABLE clinical_medication_administrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), patient_id uuid NOT NULL REFERENCES patients(id), order_id uuid REFERENCES clinical_medication_orders(id), medication text NOT NULL, administered_at timestamptz NOT NULL, dose_value numeric(12,3), dose_unit text, status text NOT NULL CHECK(status IN ('completed','not_done','in_progress')), source_reference text NOT NULL, UNIQUE(organization_id,patient_id,source_reference));
CREATE TABLE pharmacy_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), patient_id uuid NOT NULL REFERENCES patients(id), title text NOT NULL, summary text NOT NULL, review_status text NOT NULL CHECK(review_status IN ('pending','reviewed')), authored_at timestamptz NOT NULL, source_reference text NOT NULL, UNIQUE(organization_id,patient_id,source_reference));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['clinical_allergies','clinical_measurements','clinical_labs','clinical_medication_orders','clinical_medication_administrations','pharmacy_assessments'] LOOP EXECUTE format('CREATE INDEX %I ON %I(patient_id)',t||'_patient_idx',t); EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organization_id = nullif(current_setting(''app.organization_id'',true),'''')::uuid)',t||'_tenant',t); EXECUTE format('GRANT SELECT ON %I TO oncopharma_app',t); END LOOP; END $$;
